#!/usr/bin/env python3
"""Populate the knowledge base with medically grounded radiology guidance for NIH ChestX-ray labels."""

from __future__ import annotations

from pathlib import Path

DISEASES = [
    "Atelectasis",
    "Cardiomegaly",
    "Consolidation",
    "Edema",
    "Effusion",
    "Emphysema",
    "Fibrosis",
    "Hernia",
    "Infiltration",
    "Mass",
    "Nodule",
    "Pleural_Thickening",
    "Pneumonia",
    "Pneumothorax",
]

GUIDELINES = {
    "Atelectasis": """Atelectasis is a loss of lung volume caused by alveolar collapse or reduced inflation. On chest radiography, it commonly appears as plate-like or linear opacity, increased density in the affected lung base, and, when significant, elevation of the hemidiaphragm or shift of fissures toward the collapsed segment. Subsegmental atelectasis may be subtle and can mimic pneumonia or pleural fluid if volume loss is not appreciated.\n\nThe main differential diagnosis includes lower-lobe consolidation, pleural effusion, and focal pneumonia. Clinical correlation is essential because atelectasis can be caused by mucus plugging, postoperative states, diaphragmatic splinting, or obstructive lesions. When present, associated findings such as small airway obstruction or elevated hemidiaphragm help support the diagnosis.\n\nRecommended workup usually includes review of the patient history, symptom acuity, and recent surgery or immobility. A focused chest radiograph may be repeated after incentive spirometry or bronchodilator therapy when clinically appropriate, while persistent or asymmetric atelectasis warrants further evaluation for obstructing endobronchial lesions, malignancy, or occult infection.""",
    "Cardiomegaly": """Cardiomegaly is radiographic enlargement of the cardiac silhouette beyond expected normal limits relative to thoracic width. On a frontal chest radiograph, the heart may appear enlarged with widened cardiothoracic ratio, increased central vascular prominence, or a globular silhouette in cases of severe chamber enlargement. Cardiomegaly is a finding rather than a specific diagnosis and can arise from volume overload, chronic hypertension, valvular disease, ischemic cardiomyopathy, or pericardial disease.\n\nThe differential diagnosis includes physiologic variation, chest wall deformity, obesity, and technical magnification factors. A true enlarged cardiac silhouette should be interpreted together with clinical context and the presence of pulmonary vascular congestion, pleural effusions, or pulmonary edema. Marked enlargement without pulmonary findings can also reflect chronic cardiomyopathy or prior cardiac surgery.\n\nRecommended next steps include bedside assessment of symptoms and signs of heart failure, review of prior imaging, and echocardiography when clinically indicated. If cardiomegaly is associated with pulmonary vascular redistribution, edema, or pleural effusions, the workup should progress toward heart failure evaluation, volume status assessment, and management of underlying cardiac disease.""",
    "Consolidation": """Consolidation refers to replacement of air in the alveoli with fluid, inflammatory exudate, or cells, producing a region of increased opacity on chest radiography. Typical findings include homogeneous or patchy opacification that may have air bronchograms, often in a lobar or segmental distribution. Pneumonic consolidation is commonly associated with fever, cough, and focal symptoms, but aspiration or inflammatory processes can produce similar patterns.\n\nThe main differential diagnosis includes atelectasis, pulmonary edema, organizing pneumonia, and focal mass; distinguishing features such as volume loss, air bronchograms, and associated pleural effusion help guide interpretation. In some cases, collapsed lung appears denser but may show volume loss, whereas consolidation typically preserves or increases volume.\n\nRecommended workup generally includes clinical assessment, microbiologic evaluation when infection is suspected, and repeat imaging when the appearance is atypical or the patient does not improve. Persistent focal consolidation should prompt consideration of malignancy, pulmonary abscess, organizing pneumonia, or alternative infectious etiologies, and may justify CT for further characterization.""",
    "Edema": """Pulmonary edema is characterized by excessive extravascular fluid in the lungs, often producing bilateral perihilar opacities, vascular redistribution, and diffuse interstitial or alveolar infiltrates. On radiographs, cardiogenic edema typically shows cephalization of pulmonary vessels, Kerley B lines, and symmetric lower lobe or diffuse alveolar shadowing. Noncardiogenic edema can appear similar but is often associated with acute lung injury, sepsis, or drug toxicity without marked cardiomegaly.\n\nThe differential diagnosis includes diffuse infection, hemorrhage, inflammatory pneumonitis, and chronic interstitial lung disease. A useful point is that pulmonary edema usually has a more diffuse symmetric pattern and is often accompanied by pleural effusions or vascular congestion. However, the radiograph alone is not definitive, and an accurate diagnosis depends on clinical status and oxygenation.\n\nRecommended next steps include assessment of hemodynamics, oxygen requirement, and cardiac status, with bedside echocardiography or urgent medical evaluation when acute pulmonary edema is suspected. Management is guided by the underlying cause, and radiographic follow-up can help confirm improvement in alveolar flooding after treatment.""",
    "Effusion": """A pleural effusion is fluid in the pleural space, which on a frontal chest radiograph typically appears as a blunting of the costophrenic angle and, with larger volumes, a meniscus-shaped density layering in the lower hemithorax. Small effusions can be subtle, while larger effusions may cause mediastinal shift away from the affected side if the collection is substantial. The fluid may be transudative or exudative, and imaging cannot always differentiate etiology by appearance alone.\n\nThe differential diagnosis includes atelectasis, diaphragmatic elevation, pleural thickening, and less commonly a mass or consolidation that mimics fluid. Loculated effusions can form unusual shapes and may require ultrasound or CT to define the extent and loculation. If associated with pulmonary opacities, infection or malignancy should be considered in addition to simple fluid accumulation.\n\nRecommended workup usually includes targeted history for heart failure, infection, malignancy, and trauma, followed by ultrasound when the fluid is uncertain or loculated. Thoracentesis is indicated when the effusion is new, unilateral, unexplained, or associated with significant symptoms, in order to establish the cause and guide treatment.""",
    "Emphysema": """Emphysema is a chronic obstructive airspace disease characterized by destruction of alveolar walls and hyperinflation. On chest radiography, classic findings include increased anteroposterior diameter, low flattened diaphragms, increased retrosternal airspace, and diminished vascular markings at the lung periphery. Hyperinflation can produce a barrel chest appearance and may be associated with bullae or focal lucencies.\n\nThe differential diagnosis includes chronic bronchitis, asthma, bronchiectasis, and bullous lung disease. Imaging often needs to be interpreted alongside smoking history and pulmonary function testing because lesions can overlap with asthma or other chronic obstructive phenotypes. Bullae can also mimic cystic changes, and not all hyperinflated chest radiographs represent emphysema.\n\nRecommended workup includes pulmonary function tests, smoking cessation counseling, and assessment for acute exacerbations. Chest CT may be useful when the diagnosis is uncertain or when there is concern for bronchogenic carcinoma, giant bullae, or other structural lung disease.""",
    "Fibrosis": """Pulmonary fibrosis is a chronic interstitial process marked by architectural distortion and increased linear or reticular opacities in the lung parenchyma. Radiographically, fibrosis may appear as reticular opacities, traction bronchiectasis, volume loss, and a lower-lung-predominant pattern in idiopathic pulmonary fibrosis or as more diffuse changes in other fibrotic disorders. The pattern can be subtle early on and progressively more pronounced with advanced disease.\n\nThe differential diagnosis includes chronic pneumonitis, postinfectious scarring, radiation fibrosis, and pulmonary edema. Findings such as traction bronchiectasis and subpleural basilar predominance help support fibrotic change rather than simple inflammation or edema. In some cases, scarcity of pleural effusion or lack of diffuse alveolar opacities can help distinguish fibrosis from acute lung injury.\n\nRecommended next steps typically include clinical history, pulmonary function testing, and review of exposure history, autoimmune disease, and prior chest radiation. High-resolution CT is often useful for confirming a fibrotic pattern and determining whether the process is typical or requires biopsy and specialist evaluation.""",
    "Hernia": """A diaphragmatic hernia is the protrusion of abdominal contents into the thoracic cavity through a defect or weakness in the diaphragm. On chest radiographs, this may appear as a focal lucent area above the diaphragm, bowel gas pattern in the thorax, or displaced mediastinal structures depending on the hernia type and size. Morgagni and Bochdalek hernias are among the classic congenital forms, while hiatal hernias are frequently seen on the subdiaphragmatic region and may be more subtle on a standard upright chest view.\n\nThe differential diagnosis includes bowel in the thorax from trauma, eventration of the diaphragm, cystic lung lesions, and congenital diaphragmatic abnormalities. Clinical suspicion is important because some hernias are asymptomatic while others produce respiratory compromise, bowel obstruction, or vomiting. Small hernias can be overlooked, especially if the stomach bubble or bowel gas pattern is not recognized.\n\nRecommended workup often includes a focused chest or abdominal radiograph and, when uncertainty remains, CT or upper GI contrast evaluation. Surgical evaluation is warranted when symptoms, incarceration, or volvulus is suspected, especially in acute presentations.""",
    "Infiltration": """Infiltration is a broad radiographic term for abnormal opacification within the lung caused by inflammation, edema, hemorrhage, or lesser-known parenchymal processes. They may appear as ill-defined patchy or linear opacities that do not conform to a classic lobar distribution, often making interpretation less specific than pneumonia or atelectasis. Infiltrate findings can overlap substantially with infection, aspiration, edema, or early organizing pneumonia.\n\nThe differential diagnosis includes pneumonia, pulmonary edema, aspiration, hemorrhage, and inflammatory lung disease. The term is often descriptive rather than diagnostic; the exact etiology depends on the pattern of opacity and the clinical setting. A reticular or diffuse nodular infiltrate suggests a different process than a focal patch of consolidation.\n\nRecommended next steps generally include correlation with symptoms, oxygenation, fever, and sputum production. Repeat imaging, infectious workup, and consideration of CT are appropriate when the infiltrate is persistent, atypical, or associated with systemic illness.""",
    "Mass": """A pulmonary mass is a rounded or irregular opacity that is at least 3 cm in diameter and may represent a primary lung neoplasm, metastatic lesion, or focal infection. On chest radiography, a mass usually appears as a well-defined or irregular lesion that may be associated with lobar atelectasis, pleural effusion, hilar adenopathy, or adjacent soft-tissue density. The margin and location can provide clues, but imaging alone often cannot distinguish benign from malignant lesions.\n\nThe differential diagnosis includes pneumonia, organizing pneumonia, lung abscess, large granuloma, and less commonly focal fibrosis or infarct. A spiculated lesion or associated adenopathy raises concern for malignancy, whereas a smooth and well-defined lesion may be more consistent with a benign process. Clinical context, smoking history, and prior imaging are crucial.\n\nRecommended workup typically includes chest CT for better characterization, evaluation of local invasion, and staging of mediastinal or hilar disease. If suspicious, tissue diagnosis through bronchoscopy, biopsy, or PET-CT may be warranted depending on location and patient factors.""",
    "Nodule": """A pulmonary nodule is a rounded opacity measuring less than 3 cm, often seen incidentally on chest imaging. Typical radiographic features include a small, circumscribed lesion with variable density and, if calcified, a benign pattern such as popcorn or dense central calcification. A smooth margin and stable size over time are reassuring, whereas irregular margins, spiculation, or growth raise concern.\n\nThe differential diagnosis includes granuloma, infectious focus, previous inflammatory scar, primary lung cancer, and metastatic disease. Characterization depends on size, density, location, and interval growth; solitary nodules require careful comparison with prior imaging. Some nodules represent benign infectious granulomas, while others may be early malignancies.\n\nRecommended workup generally includes comparison with prior imaging and CT for nodule morphology, density, and size. If the lesion is indeterminate or enlarging, a management algorithm incorporating risk factors, follow-up interval imaging, or biopsy is appropriate.""",
    "Pleural_Thickening": """Pleural thickening is an abnormal increase in pleural density or pleural rind seen on chest imaging. On chest radiographs, it often appears as a smooth or irregular pleural line that may be unilateral or bilateral and can accompany thickened fissures or adjacent pleural fluid. It may reflect prior inflammation, asbestos exposure, chronic pleuritis, or malignancy, and can be difficult to distinguish from peripheral fibrosis or scarring without cross-sectional imaging.\n\nThe differential diagnosis includes pleural effusion, passive atelectasis, chest wall lesions, and adjacent pulmonary fibrosis. Smooth pleural thickening may be more benign or chronic, while nodular or irregular pleural thickening raises concern for malignancy or pleural disease. Clinical exposure history, including asbestos or prior chest surgery, is important.\n\nRecommended workup often involves chest CT to define the extent, loculation, and relationship to the lung and chest wall. If pleural thickening is nodular or associated with effusion, malignant pleural disease or prior inflammatory processes should be considered, and further biopsy or thoracic consultation may be warranted.""",
    "Pneumonia": """Pneumonia is an infection causing alveolar inflammation and replacement of air with inflammatory exudate. Radiographically, it often appears as focal or multifocal airspace opacity with or without air bronchograms, and lobar involvement may be seen in typical bacterial pneumonia. The pattern can vary by organism, host immune status, and aspiration risk, making radiographic appearance a clue rather than a definitive diagnosis.\n\nThe differential diagnosis includes atelectasis, pulmonary edema, pulmonary embolism, organizing pneumonia, and lung cancer with postobstructive consolidation. Features such as lobar distribution, air bronchograms, and a more homogeneous opacity support pneumonia, whereas diffuse interstitial opacities or vascular redistribution may suggest alternative diagnoses. Clinical symptoms such as fever, cough, and dyspnea should be correlated with the image.\n\nRecommended workup includes clinical assessment, oxygen status, and targeted laboratory and microbiologic evaluation when clinically indicated. If the patient is hospitalized or not improving, repeat imaging and consideration of CT, bronchoscopy, or alternative diagnoses such as abscess or malignancy are appropriate.""",
    "Pneumothorax": """Pneumothorax is air in the pleural space, causing partial or complete collapse of the affected lung. On chest radiography, it typically appears as a pleural line with absent peripheral lung markings beyond it, often at the apices in upright films. Large pneumothoraces can produce marked asymmetry or mediastinal shift depending on severity, while small and loculated collections may be subtle and require expiratory or lateral decubitus imaging.\n\nThe differential diagnosis includes bullous lung disease, subcutaneous emphysema, and skin folds or overlying artifacts. Bilateral pneumothoraces or a very large pneumothorax can be life-threatening and should be interpreted urgently in the context of patient symptoms. In trauma or postoperative settings, a simple pneumothorax may coexist with hemothorax or contusion.\n\nRecommended next steps include immediate assessment of hemodynamic stability and chest tube placement or aspiration based on the size and symptoms, especially in unstable patients. Follow-up imaging is used to confirm resolution and to assess for recurrence or underlying pleural disease.""",
}


def populate_knowledge_base() -> None:
    root = Path(__file__).resolve().parents[1]
    documents_dir = root / "knowledge_base" / "documents"
    documents_dir.mkdir(parents=True, exist_ok=True)

    for disease in DISEASES:
        file_path = documents_dir / f"{disease}_guidelines.txt"
        content = GUIDELINES[disease].strip() + "\n"
        file_path.write_text(content, encoding="utf-8")
        print(f"Wrote {file_path.name}")

    print(f"Created {len(DISEASES)} guideline files in {documents_dir}")


if __name__ == "__main__":
    populate_knowledge_base()
